import math


def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])


def find_zero(xs: list):
    """ xs are coefficients of a polynomial.
    find_zero find x such that poly(x) = 0.
    find_zero returns only only zero point, even if there are many.
    Moreover, find_zero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> round(find_zero([1, 2]), 2) # f(x) = 1 + 2x
    -0.5
    >>> round(find_zero([-6, 11, -6, 1]), 2) # (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
    """
    coeffs = [float(c) for c in xs]
    while coeffs and coeffs[-1] == 0.0:
        coeffs.pop()

    if not coeffs:
        return 0.0
    if len(coeffs) == 1:
        return 0.0
    if len(coeffs) == 2:
        return -coeffs[0] / coeffs[1]

    def evaluate(x: float) -> float:
        y = 0.0
        for c in reversed(coeffs):
            y = y * x + c
        return y

    def sign(v: float) -> int:
        if v > 0.0:
            return 1
        if v < 0.0:
            return -1
        return 0

    lead = coeffs[-1]
    try:
        max_ratio = max(abs(c / lead) for c in coeffs[:-1])
    except (ZeroDivisionError, OverflowError):
        max_ratio = 1.0

    bound = 1.0 + max_ratio
    if not math.isfinite(bound) or bound <= 0.0:
        bound = 1.0

    a = -bound
    b = bound
    fa = evaluate(a)
    fb = evaluate(b)

    bracketed = False
    for _ in range(100):
        if not (math.isfinite(fa) and math.isfinite(fb)):
            break
        if fa == 0.0:
            return a
        if fb == 0.0:
            return b
        if sign(fa) != sign(fb):
            bracketed = True
            break
        a *= 2.0
        b *= 2.0
        fa = evaluate(a)
        fb = evaluate(b)

    if not bracketed:
        deriv = [i * coeffs[i] for i in range(1, len(coeffs))]
        if not deriv:
            return 0.0

        def evaluate_deriv(x: float) -> float:
            y = 0.0
            for c in reversed(deriv):
                y = y * x + c
            return y

        for start in (0.0, 1.0, -1.0, 2.0, -2.0, 0.5, -0.5, 10.0, -10.0):
            x = float(start)
            for _ in range(100):
                fx = evaluate(x)
                if abs(fx) < 1e-12:
                    return x
                dfx = evaluate_deriv(x)
                if dfx == 0.0:
                    x += 1e-6 if x >= 0.0 else -1e-6
                    continue
                x_new = x - fx / dfx
                if not math.isfinite(x_new):
                    x += 1e-6 if x >= 0.0 else -1e-6
                    continue
                if abs(x_new - x) < 1e-12:
                    x = x_new
                    break
                x = x_new

            if abs(evaluate(x)) < 1e-8:
                return x

        if math.isfinite(a) and math.isfinite(b):
            return (a + b) / 2.0
        return 0.0

    for _ in range(100):
        mid = (a + b) / 2.0
        if mid == a or mid == b:
            break

        fm = evaluate(mid)
        if not math.isfinite(fm):
            break
        if abs(fm) < 1e-12:
            return mid

        if sign(fm) == sign(fa):
            a = mid
            fa = fm
        else:
            b = mid
            fb = fm

    return (a + b) / 2.0

